const qs=s=>document.querySelector(s);const svc={single:{name:'Single Room Massage',duration:60,price:800,min:1,max:1},couples:{name:'Couples Suite',duration:60,price:1800,min:2,max:2},family:{name:'Barkada / Family Spa Lounge',duration:90,price:4000,min:1,max:6}};const peso=n=>'₱'+n.toLocaleString('en-PH');const dateToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
async function request(body){const r=await fetch('/.netlify/functions/api',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let d;try{d=await r.json()}catch{throw Error('Booking is not available yet. Please try again later.')}if(!r.ok)throw Error(d.error||'Booking is not available yet.');return d}function msg(el,text){el.textContent=text}function formatted(d){return new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',dateStyle:'full',timeStyle:'short'}).format(new Date(d))}
const form=qs('#booking-form');let availabilityVersion=0,reviewing=false;qs('#date').min=dateToday();qs('#date').value=dateToday();
function resetReview(){reviewing=false;qs('#review-box')?.remove();form.querySelector('[type=submit]').textContent='Review appointment'}
function refreshPrice(){const key=qs('#service').value,s=svc[key],n=Number(qs('#guests').value),extra=key==='family'?Math.max(0,n-4)*750:0;const total=s.price+extra;qs('#price').textContent=peso(total);qs('#payment-due').textContent=`${qs('#payment-option').value==='downpayment'?'50% down payment':'Full payment'}: ${peso(qs('#payment-option').value==='downpayment'?total/2:total)} · Receipt is subject to staff review.`;qs('#details').textContent=`${n} ${n===1?'guest':'guests'} · ${s.duration} minutes${key==='family'?` · ${peso(s.price)} base${extra?` + ${peso(extra)} extra`: ' for up to four guests'}`:''}`;qs('#pricing-note').textContent=key==='family'?'₱4,000 covers up to four guests; ₱750 per extra guest.':'';resetReview()}
async function availability(){let seq=++availabilityVersion,select=qs('#time');select.replaceChildren(new Option('Checking availability…',''));msg(qs('#availability-status'),'Checking current room availability…');try{const d=await request({action:'availability',service:qs('#service').value,date:qs('#date').value});if(seq!==availabilityVersion)return;select.replaceChildren(new Option(d.slots.length?'Choose a time':'No available times',''));d.slots.forEach(x=>select.add(new Option(x.label,x.value)));msg(qs('#availability-status'),d.slots.length?'Times shown are currently available.':'No available times for this date.')}catch(e){if(seq!==availabilityVersion)return;select.replaceChildren(new Option('Availability unavailable',''));msg(qs('#availability-status'),e.message)}resetReview()}
function updateService(){const key=qs('#service').value,s=svc[key],select=qs('#guests');select.replaceChildren();for(let i=s.min;i<=s.max;i++)select.add(new Option(`${i} ${i===1?'guest':'guests'}`,i));if(key==='family')select.value='4';const img=qs('.planner-art img'),asset=window.SPA_ASSETS[key];if(img&&asset){img.hidden=false;img.onerror=()=>{img.hidden=true};img.src=asset.src;img.alt=asset.alt}refreshPrice();availability();loadMonth()}
function updateHealth(){const value=qs('#health').value,yes=value==='yes';qs('#health-detail-label').hidden=!yes;qs('#health-details').required=yes;qs('#booking-choices').disabled=!value||(yes&&!qs('#health-details').value.trim());resetReview()}qs('#health').addEventListener('change',updateHealth);qs('#health-details').addEventListener('input',updateHealth);qs('#service').addEventListener('change',updateService);qs('#guests').addEventListener('change',refreshPrice);qs('#payment-option').addEventListener('change',refreshPrice);qs('#customer-phone').addEventListener('input',e=>{e.target.value=e.target.value.replace(/[^0-9]/g,'')});qs('#date').addEventListener('change',()=>{availability();calendarMonth=qs('#date').value.slice(0,7);loadMonth()});form.addEventListener('input',e=>{if(e.target.id!=='terms')resetReview()});form.addEventListener('change',e=>{if(e.target.id==='time'||e.target.id==='receipt')resetReview()});document.querySelectorAll('[data-select]').forEach(a=>a.addEventListener('click',()=>{qs('#service').value=a.dataset.select;updateService()}));
function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('Could not read receipt.'));r.readAsDataURL(file)})}
let calendarMonth=qs('#date').value.slice(0,7),monthVersion=0;function moveMonth(value,delta){const [y,m]=value.split('-').map(Number),d=new Date(Date.UTC(y,m-1+delta,1));return d.toISOString().slice(0,7)}function dateCaption(date){return new Intl.DateTimeFormat('en-PH',{timeZone:'UTC',weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(new Date(date+'T00:00:00Z'))}async function loadMonth(){const seq=++monthVersion,month=calendarMonth,service=qs('#service').value,container=qs('#availability-days');qs('#availability-month').textContent=new Intl.DateTimeFormat('en-PH',{timeZone:'UTC',month:'long',year:'numeric'}).format(new Date(month+'-01T00:00:00Z'));qs('#availability-prev').disabled=month<=dateToday().slice(0,7);container.replaceChildren();msg(qs('#month-status'),'Checking dates…');try{const result=await request({action:'availabilityMonth',service,month});if(seq!==monthVersion)return;const start=new Date(month+'-01T00:00:00Z').getUTCDay();['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach(d=>{const el=document.createElement('span');el.className='calendar-weekday';el.textContent=d;container.append(el)});for(let n=0;n<start;n++)container.append(document.createElement('span'));result.days.forEach(day=>{const button=document.createElement('button');button.type='button';button.textContent=String(Number(day.date.slice(-2)));const count=day.date<dateToday()?0:day.count;button.disabled=count===0;button.className=count?'available-day':'unavailable-day';button.setAttribute('aria-label',`${dateCaption(day.date)}: ${count} available ${count===1?'time':'times'}`);if(day.date===qs('#date').value)button.setAttribute('aria-current','date');button.onclick=()=>{qs('#date').value=day.date;container.querySelectorAll('[aria-current]').forEach(el=>el.removeAttribute('aria-current'));button.setAttribute('aria-current','date');availability()};container.append(button)});msg(qs('#month-status'),'Highlighted dates have available appointment times.')}catch(err){if(seq!==monthVersion)return;msg(qs('#month-status'),'Could not load date availability. Please try again.')}}qs('#availability-prev').onclick=()=>{calendarMonth=moveMonth(calendarMonth,-1);loadMonth()};qs('#availability-next').onclick=()=>{calendarMonth=moveMonth(calendarMonth,1);loadMonth()};
form.addEventListener('submit',async e=>{e.preventDefault();const file=qs('#receipt').files[0];if(!file||file.size>4000000||!['image/jpeg','image/png','application/pdf'].includes(file.type)){msg(qs('#booking-status'),'Choose a PNG, JPEG or PDF receipt under 4 MB.');return}if(!reviewing){const box=document.createElement('div');box.id='review-box';box.className='review-box';const text=document.createElement('p');const health=qs('#health').value==='yes'?`Yes — ${qs('#health-details').value}`:'No';text.textContent=`Review: ${svc[qs('#service').value].name} · ${qs('#guests').value} guest(s) · ${formatted(qs('#time').value)} · ${qs('#price').textContent}. ${qs('#payment-due').textContent} Contact: ${qs('#customer-phone').value}. Health declaration: ${health}. Receipt: ${file.name}.`;box.append(text);form.querySelector('[type=submit]').before(box);form.querySelector('[type=submit]').textContent='Confirm booking';reviewing=true;msg(qs('#booking-status'),'Review your details and terms, then confirm your booking.');return}const button=form.querySelector('[type=submit]');button.disabled=true;msg(qs('#booking-status'),'Saving your appointment…');try{const result=await request({action:'book',service:qs('#service').value,guests:Number(qs('#guests').value),date:qs('#date').value,start:qs('#time').value,name:qs('#customer-name').value,email:qs('#customer-email').value,phone:qs('#customer-phone').value,paymentOption:qs('#payment-option').value,health:qs('#health').value==='yes',details:qs('#health-details').value,terms:qs('#terms').checked,receipt:{type:file.type,data:await readFile(file)}});const a=result.appointment,box=qs('#booking-result');box.replaceChildren();const p=document.createElement('p');p.textContent=`Booked — receipt pending review. Reference ${a.reference} · ${svc[a.service].name} · room ${a.room} · ${formatted(a.start)} · ${peso(a.price)} · ${a.paymentOption==='downpayment'?'Down payment':'Full payment'} due: ${peso(a.amountDue)}.`;const link=document.createElement('a');link.href=result.managementLink;link.textContent='Save this private link to manage your appointment';box.append(p,link);msg(qs('#booking-status'),result.emailSent?'Confirmation email accepted for delivery.':'Booking saved, but the confirmation email was not sent. Save the private management link below.');form.querySelectorAll('fieldset').forEach(x=>x.disabled=true)}catch(err){msg(qs('#booking-status'),err.message);button.disabled=false;resetReview();availability()}});updateService();
